    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        controller = context.get("controller")
        if controller is None or not hasattr(controller, "run_python_script"):
            return self._error("controller.run_python_script is required")
        port = int(dict(context.get("params") or {}).get("port", 4350))
        try:
            state = self._fetch_state(controller, port)
            observation = context.get("final_observation")
            if observation is None:
                observation = controller.observe(include_ui_tree=False, include_screenshot_data=False)
            return self.evaluate_state(
                state,
                foreground_app=str(getattr(observation, "foreground_app", "") or ""),
                foreground_window=str(getattr(observation, "foreground_window", "") or ""),
            )
        except Exception as exc:
            return self._error(f"OpenTwitter evaluation error: {type(exc).__name__}: {exc}")

    @classmethod
    def evaluate_state(
        cls,
        state: Mapping[str, Any],
        *,
        foreground_app: str = "opentwitter.exe",
        foreground_window: str = "OpenTwitter",
    ) -> EvalResult:
        checks: list[dict[str, Any]] = []
        all_events = _items(state, "events")
        login_events = [
            row for row in all_events
            if row.get("type") == "session_login_success" and str(row.get("handle") or "").casefold() == "alex"
        ]
        login = login_events[-1] if login_events else None
        start_seq = _seq(login)
        events = [row for row in all_events if _seq(row) >= start_seq] if login else []
        event_order: list[tuple[str, int]] = []

        session = state.get("session") if isinstance(state.get("session"), Mapping) else {}
        session_user = session.get("user") if isinstance(session.get("user"), Mapping) else {}
        login_passed = bool(
            login
            and session.get("loggedIn") is True
            and str(session_user.get("handle") or "").casefold() == "alex"
            and str(session_user.get("email") or "").casefold() == "alex@opentwitter.local"
        )
        checks.append(cls._check(CHECKPOINT_SPECS[0], login_passed, {
            "event": _summary(login), "session": {"loggedIn": session.get("loggedIn"), "user": dict(session_user)}
        }))
        event_order.append(("login", _seq(login)))

        posts = _items(state, "posts")
        post_event_rows: list[dict[str, Any] | None] = []
        for index, expected_text in enumerate(RULESET_SPEC["posts"], start=1):
            matches = [
                row for row in posts
                if row.get("authorHandle") == "alex"
                and row.get("text") == expected_text
                and row.get("topic") == "Updates"
            ]
            target = matches[0] if len(matches) == 1 else None
            matching_events = [
                row for row in events
                if target
                and row.get("type") == "post_created"
                and row.get("postId") == target.get("id")
                and row.get("text") == expected_text
                and row.get("topic") == "Updates"
            ]
            event = matching_events[0] if len(matching_events) == 1 else None
            passed = target is not None and event is not None
            checks.append(cls._check(CHECKPOINT_SPECS[index], passed, {
                "object_count": len(matches), "object": _summary(target), "event": _summary(event)
            }))
            post_event_rows.append(event)
            event_order.append((f"post_{index}", _seq(event)))

        final_sets = explore.active_sets(state)
        for offset, query in enumerate(RULESET_SPEC["trend_queries"], start=5):
            runtime_query = RULESET_SPEC["trend_runtime_queries"][query]
            engagement = explore.first_post_engagement(
                posts=posts,
                all_events=all_events,
                session_events=events,
                query=runtime_query,
                final_sets=final_sets,
                account_handle=RULESET_SPEC["account"]["handle"],
            )
            checks.append(cls._check(CHECKPOINT_SPECS[offset], engagement["passed"], {
                "query": query,
                "runtime_query": runtime_query,
                "target_rule": "first post the Explore stream listed at the view (or the first it held before posts the agent published)",
                "matching_post": engagement["first_post"],
                "matching_view_count": engagement["matching_view_count"],
                "view": engagement["view"],
                "already_active_at_view": engagement.get("already_active_at_view", {}),
                "ordered_actions": engagement["ordered_actions"],
                "active_final": engagement["active_final"],
                **({"attempts": engagement["attempts"]} if "attempts" in engagement else {}),
            }))
            event_order.append((f"trend_{offset - 4}", engagement["terminal_seq"]))

        messages = _items(state, "messages")
        message_event_rows: list[dict[str, Any] | None] = []
        for offset, expected in enumerate(RULESET_SPEC["messages"], start=9):
            objects = [
                row for row in messages
                if row.get("handle") == expected["handle"]
                and row.get("text") == expected["text"]
                and row.get("outbound") is True
            ]
            matching_events = [
                row for row in events
                if row.get("type") == "message_sent"
                and row.get("handle") == expected["handle"]
                and row.get("text") == expected["text"]
            ]
            event = matching_events[0] if len(matching_events) == 1 else None
            passed = len(objects) == 1 and event is not None
            checks.append(cls._check(CHECKPOINT_SPECS[offset], passed, {
                "object_count": len(objects), "object": _summary(objects[0] if len(objects) == 1 else None),
                "event_count": len(matching_events), "event": _summary(event),
            }))
            message_event_rows.append(event)
            event_order.append((f"message_{offset - 8}", _seq(event)))

        notifications = _items(state, "notifications")
        mark_events = [row for row in events if row.get("type") == "notifications_marked_read"]
        mark_event = mark_events[0] if mark_events else None
        notifications_passed = bool(notifications) and all(row.get("read") is True for row in notifications) and mark_event is not None
        checks.append(cls._check(CHECKPOINT_SPECS[13], notifications_passed, {
            "notification_count": len(notifications),
            "unread_count": sum(1 for row in notifications if row.get("read") is not True),
            "event_count": len(mark_events),
            "first_event": _summary(mark_event),
        }))
        event_order.append(("notifications", _seq(mark_event)))

        current_user = state.get("currentUser") if isinstance(state.get("currentUser"), Mapping) else {}
        profile_expected = RULESET_SPEC["profile"]
        profile_passed = all(current_user.get(key) == value for key, value in profile_expected.items())
        profile_views = [
            row for row in events
            if row.get("type") == "timeline_view"
            and row.get("view") == "profile"
            and row.get("handle") == "alex"
        ]
        profile_view = profile_views[-1] if profile_views else None
        checks.append(cls._check(CHECKPOINT_SPECS[14], profile_passed and profile_view is not None, {
            "current_user": {key: current_user.get(key) for key in profile_expected},
            "profile_view": _summary(profile_view),
        }))
        event_order.append(("profile", _seq(profile_view)))

        order_passed = all(seq >= 0 for _, seq in event_order) and all(
            left[1] < right[1] for left, right in zip(event_order, event_order[1:])
        )
        checks.append({
            "name": "opentwitter.accessibility.business_order",
            "value_contract_id": "opentwitter.accessibility.business_order",
            "instruction_steps": list(range(1, 77)),
            "match_mode": "ORDERED_EXACT",
            "expected": [name for name, _ in event_order],
            "actual": [{"name": name, "seq": seq} for name, seq in event_order],
            "passed": order_passed,
        })

        foreground_passed = foreground_app.casefold() in {"opentwitter", "opentwitter.exe"} and "opentwitter" in foreground_window.casefold()
        checks.append({
            "name": "opentwitter.accessibility.foreground",
            "value_contract_id": "opentwitter.accessibility.foreground",
            "instruction_steps": list(range(69, 77)),
            "match_mode": "FINAL_UI_APP_EXACT",
            "expected": {"app": "opentwitter.exe", "window": "OpenTwitter"},
            "actual": {"app": foreground_app, "window": foreground_window},
            "passed": foreground_passed,
        })

        covered = {step for spec in CHECKPOINT_SPECS for step in spec["steps"]}
        if covered != set(range(1, 77)):
            return cls._error("checkpoint map does not cover exactly steps 1..76", checks)
        failed = [row["name"] for row in checks if not row.get("passed")]
        metadata = {
            "task_id": TASK_ID,
            "read_only": True,
            "source_state_mode": "human_completed_eval_only",
            "business_state_mutations": [],
            "evaluator_id": EVALUATOR_ID,
            "ruleset_sha256": RULESET_SHA256,
            "ruleset_spec": RULESET_SPEC,
            "step_groups": STEP_GROUPS,
            "checkpoint_specs": CHECKPOINT_SPECS,
            "covered_instruction_steps": list(range(1, 77)),
            "checks": checks,
            "failed_checks": failed,
        }
        return EvalResult(
            status=EvalStatus.FAIL if failed else EvalStatus.PASS,
            message=("OpenTwitter accessibility/performance evaluation failed: " + ", ".join(failed)) if failed else "All OpenTwitter accessibility/performance checks passed",
            metadata=metadata,
        )

    @staticmethod
    def _check(spec: Mapping[str, Any], passed: bool, actual: Any) -> dict[str, Any]:
        return {
            "name": str(spec["value_contract_id"]),
            "value_contract_id": spec["value_contract_id"],
            "instruction_steps": list(spec["steps"]),
            "match_mode": spec["match_mode"],
            "expected": spec["expected"],
            "actual": actual,
            "passed": bool(passed),
        }

    @classmethod
    def _error(cls, message: str, checks: list[dict[str, Any]] | None = None) -> EvalResult:
        rows = checks or []
        return EvalResult(
            status=EvalStatus.ERROR,
            message=message,
            metadata={
                "task_id": TASK_ID,
                "read_only": True,
                "source_state_mode": "human_completed_eval_only",
                "business_state_mutations": [],
                "evaluator_id": EVALUATOR_ID,
                "ruleset_sha256": RULESET_SHA256,
                "ruleset_spec": RULESET_SPEC,
                "step_groups": STEP_GROUPS,
                "checkpoint_specs": CHECKPOINT_SPECS,
                "checks": rows,
                "failed_checks": [row.get("name") for row in rows if not row.get("passed")],
            },
        )

    @staticmethod
    def _fetch_state(controller: Any, port: int) -> Mapping[str, Any]:
        code = """import urllib.request\nwith urllib.request.urlopen(%r, timeout=8) as response:\n    print(response.read().decode('utf-8'))\n""" % f"http://127.0.0.1:{port}/api/evaluation"
        result = controller.run_python_script(code, timeout=15)
        if int(result.get("returncode", -1)) != 0:
            raise RuntimeError(str(result.get("stderr") or result.get("output") or "OpenTwitter API request failed"))
        payload = json.loads(str(result.get("stdout") or result.get("output") or ""))
        if not isinstance(payload, Mapping):
            raise TypeError("OpenTwitter evaluation payload must be an object")
        return payload
